INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (45, 'XLB', 'State Street Materials Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLB', NULL, NULL, NULL, 'In seeking to track the performance of the index, the fund employs a replication strategy. It generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes securities of companies from the following industries: chemicals; metals and mining; paper and forest products; containers and packaging; and construction materials. The fund is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:04:39', '2026-09-13 07:04:39');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (46, 'XLC', 'State Street Communication Services Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLC', NULL, NULL, NULL, 'Normally, the fund generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes companies that have been identified as Communication Services companies by the GICS®, including securities of companies from the following industries: diversified telecommunication services; wireless telecommunication services; media; entertainment; and interactive media & services. The fund is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:09:52', '2026-09-13 07:09:52');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (47, 'XLE', 'State Street Energy Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLE', NULL, NULL, NULL, 'In seeking to track the performance of the index, the fund employs a replication strategy. It generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes companies that have been identified as Energy companies by the GICS®, including securities of companies from the following industries: oil, gas and consumable fuels; and energy equipment and services. It is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:12:36', '2026-09-13 07:12:36');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (48, 'XLF', 'State Street Financial Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLF', NULL, NULL, NULL, 'The fund generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes companies that have been identified as Financial companies by the Global Industry Classification Standard, including securities of companies from the following industries: financial services; insurance; banks; capital markets; mortgage real estate investment trusts; and consumer finance. The fund is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:15:20', '2026-09-13 07:15:20');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (49, 'XLI', 'State Street Industrial Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLI', NULL, NULL, NULL, 'Under normal market conditions, the fund generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes companies that have been identified as Industrial companies by the Global Industry Classification Standard, including securities of companies from the following industries: aerospace and defense; industrial conglomerates; marine transportation. It is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:18:04', '2026-09-13 07:18:04');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (50, 'XLK', 'State Street Technology Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLK', NULL, NULL, NULL, 'In seeking to track the performance of the index, the fund employs a replication strategy, which means that the fund typically invests in substantially all of the securities represented in the index in approximately the same proportions as the index. It generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The fund is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:19:15', '2026-09-13 07:19:15');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (51, 'XLP', 'State Street Consumer Staples Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLP', NULL, NULL, NULL, 'In seeking to track the performance of the index, the fund employs a replication strategy. It generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes companies that have been identified as Consumer Staples companies by the GICS®. It is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:19:17', '2026-09-13 07:19:17');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (52, 'XLRE', 'State Street Real Estate Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLRE', NULL, NULL, NULL, 'Under normal market conditions, the fund generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes companies that have been identified as Real Estate companies by the Global Industry Classification Standard (GICS®). The fund is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:19:18', '2026-09-13 07:19:18');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (53, 'XLU', 'State Street Utilities Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLU', NULL, NULL, NULL, 'In seeking to track the performance of the index, the fund employs a replication strategy. It generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes securities of companies from the following industries: electric utilities; water utilities; multi-utilities; independent power and renewable electricity producers; and gas utilities. The fund is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:19:19', '2026-09-13 07:19:19');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (54, 'XLV', 'State Street Health Care Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLV', NULL, NULL, NULL, 'In seeking to track the performance of the index, the fund employs a replication strategy. It generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes companies from the following industries: pharmaceuticals; health care equipment & supplies; health care providers & services; biotechnology; life sciences tools & services; and health care technology. The fund is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:19:21', '2026-09-13 07:19:21');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (55, 'XLY', 'State Street Consumer Discretionary Select Sector SPDR ETF', 'NYSEArca', 'USD', 'XLY', NULL, NULL, NULL, 'The Advisor employs a replication strategy. The fund generally invests substantially all, but at least 95%, of its total assets in the securities comprising the index. The index includes companies that have been identified as Consumer Discretionary companies by the Global Industry Classification Standard (GICS®). It is non-diversified.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:19:22', '2026-09-13 07:19:22');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (56, 'SPY', 'State Street SPDR S&P 500 ETF Trust', 'NYSEArca', 'USD', 'SPY', NULL, NULL, NULL, 'The trust seeks to achieve its investment objective by holding a portfolio of the common stocks that are included in the index (the “Portfolio”), with the weight of each stock in the Portfolio substantially corresponding to the weight of such stock in the index.', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-13 07:19:24', '2026-09-13 07:19:24');
INSERT INTO instruments (id, symbol, name, exchange, currency, yahoo_symbol, investing_id, sector, industry, business_summary, employees, website, street_address, city, country, phone, created_at, updated_at) VALUES (76, 'MU', 'Micron Technology, Inc.', 'NasdaqGS', 'USD', 'MU', NULL, 'Technology', 'Semiconductors', 'Micron Technology, Inc. designs, develops, manufactures, and sells memory and storage products in the United States, Taiwan, Japan, Mainland China, Hong Kong, Europe, and internationally. It operates through the Cloud Memory Business Unit; Core Data Center Business Unit; Mobile and Client Business Unit; and Automotive and Embedded Business Unit segments. The company provides memory products, including dynamic random access memory components and modules, CXL-based memory, LPDDR components and modules, graphics memory, high-bandwidth memory, and data center memory products; multichip packages (MCP) comprising embedded multimedia card-based, universal flash storage-based, and NAND-based MCPs; and technology leadership products that include 1y DRAM and G9 NAND technologies. It also offers storage products, such as data center solid-state drives (SSD), client SSD storage, and auto and industrial SSD storage; managed NAND; NAND flash; NOR flash; and memory cards. In addition, the company provides design tools, including FBGA and part decoders; DRAM power calculators; NAND power calculators; simulation models; chipset compatibility guides; serial presence-detection tools; cross-reference tools; UFSparm; SSD firmware; software and drivers; storage executive software; and obsolete part catalogs. It markets its semiconductor memory and storage products under the Micron and Crucial brands. The company serves the data center, PC, graphics, networking, automotive, industrial, and consumer embedded markets, as well as the smartphone and other mobile-device markets. It sells its products through its direct sales force, independent sales representatives, distributors, and retailers; web-based customer direct sales channel; and channel and distribution partners. Micron Technology, Inc. was founded in 1978 and is headquartered in Boise, Idaho.', 53000, 'https://www.micron.com', '8000 South Federal Way', 'Boise', 'United States', '208 368 4000', '2026-09-14 10:42:00', '2026-09-27 12:29:30');
